import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ACTIONS = ['승인', '보류', '반려'];
// 가정: 결재 대기 상태로 보는 현재 상태 (결재대기·진행중)
const OPEN_STATES = ['결재대기', '진행중'];
// 가정: 보류 처리 뒤 품의서 상태는 '보류', 승인·반려는 처리 유형과 같은 상태

@Controller('api/v1')
export class FnSfr02403Controller {
  @Get('/purchase-requests/:purchaseRequestId')
  async getPurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['purchaseRequestId'];
    return transaction(async (db) => {
      if (!/^[0-9]+$/.test(id)) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'SELECT purchase_request_id AS "purchaseRequestId", document_no AS "documentNo", title AS "title", ' +
          'purchase_content AS "purchaseContent", amount AS "amount", approval_status AS "approvalStatus", ' +
          'asset_inspection_required AS "assetInspectionRequired" ' +
          'FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Post('/purchase-requests/:purchaseRequestId/approve')
  @HttpCode(200)
  async approvePurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['purchaseRequestId'];
    const data = checks.inputOf(req.body);
    const actionType = data['actionType'];
    if (typeof actionType !== 'string' || !ACTIONS.includes(actionType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형을 승인, 보류, 반려 중에서 선택해 주세요.');
    }
    const rawOpinion = data['opinion'];
    if (rawOpinion !== undefined && rawOpinion !== null && typeof rawOpinion !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 의견 형식이 올바르지 않습니다.');
    }
    const opinion = typeof rawOpinion === 'string' && rawOpinion.trim() !== '' ? rawOpinion.trim() : null;
    if (actionType === '반려' && opinion === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려할 때는 결재 의견을 입력해 주세요.');
    }
    return transaction(async (db) => {
      if (!/^[0-9]+$/.test(id)) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT purchase_request_id AS "purchaseRequestId", approval_status AS "approvalStatus", ' +
          'approval_document_id AS "approvalDocumentId", requester_id AS "requesterId", title AS "title" ' +
          'FROM purchase_request WHERE purchase_request_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '구매품의서를 찾을 수 없습니다.');
      }
      const request = found[0];
      if (!OPEN_STATES.includes(request.approvalStatus)) {
        throw new ApiError(409, 'PURCHASE_REQUEST_ALREADY_PROCESSED', '이미 처리되었거나 결재 대기 상태가 아닌 품의서입니다.');
      }
      if (request.approvalDocumentId === null || request.approvalDocumentId === undefined) {
        throw new ApiError(422, 'APPROVER_NOT_IN_LINE', '결재선에 포함된 승인권자만 처리할 수 있습니다.');
      }
      const lines = await db.query(
        'SELECT approval_line_id AS "approvalLineId" FROM approval_line ' +
          'WHERE approval_document_id = CAST(:documentId AS bigint) ' +
          'AND approver_id = CAST(:userId AS bigint) AND action_type IS NULL ' +
          'ORDER BY line_group, sequence_no LIMIT 1',
        { documentId: request.approvalDocumentId, userId: user.id },
      );
      if (lines.length === 0) {
        throw new ApiError(422, 'APPROVER_NOT_IN_LINE', '결재선에 포함된 승인권자만 처리할 수 있습니다.');
      }
      await db.execute(
        'UPDATE approval_line SET action_type = :actionType, opinion = :opinion, processed_at = now(), updated_at = now() ' +
          'WHERE approval_line_id = CAST(:lineId AS bigint)',
        { actionType, opinion, lineId: lines[0].approvalLineId },
      );
      const newStatus = actionType;
      await db.execute(
        'UPDATE purchase_request SET approval_status = :status, updated_at = now() ' +
          'WHERE purchase_request_id = CAST(:id AS bigint)',
        { status: newStatus, id },
      );
      await db.execute(
        'UPDATE approval_document SET approval_status = :status, updated_at = now() ' +
          'WHERE approval_document_id = CAST(:documentId AS bigint)',
        { status: newStatus, documentId: request.approvalDocumentId },
      );
      await db.execute(
        'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) ' +
          "VALUES ('purchase_request', CAST(:id AS bigint), '승인', now(), CAST(:userId AS bigint), :before, :after, now(), now())",
        { id, userId: user.id, before: request.approvalStatus, after: newStatus },
      );
      await db.execute(
        'INSERT INTO notification (employee_id, notification_type, event_type, title, summary, target_type, target_id, read_yn, occurred_at, created_at, updated_at) ' +
          "VALUES (CAST(:employeeId AS bigint), 'ALERT', 'PURCHASE_REQUEST_APPROVAL', :title, :summary, 'PURCHASE_REQUEST', CAST(:id AS bigint), false, now(), now(), now())",
        {
          employeeId: request.requesterId,
          title: '구매품의 ' + actionType + ' 결과',
          summary: String(request.title) + ' 품의서가 ' + newStatus + ' 처리되었습니다.',
          id,
        },
      );
      return { purchaseRequestId: Number(id), approvalStatus: newStatus };
    });
  }
}

