import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const ACTION_OPTIONS: [string, string][] = [
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
];

const SIZE = 20;

function canApprove(status: unknown) {
  return status === '결재대기' || status === '진행중';
}

function DetailPanel({ purchaseRequestId, role }: { purchaseRequestId: number; role: string }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', `/purchase-requests/${purchaseRequestId}`, role),
    [purchaseRequestId],
  );
  if (loading) return <p>불러오는 중입니다.</p>;
  if (error) return <ErrorText text={error} />;
  if (!data) return null;
  return (
    <Pairs
      items={[
        ['문서번호', String(data.documentNo ?? '')],
        ['품의 제목', String(data.title ?? '')],
        ['구매 내용', String(data.purchaseContent ?? '')],
        ['품의 금액', <Num value={data.amount} />],
        ['결재 상태', <Badge value={data.approvalStatus} />],
        ['자산 검수 여부', data.assetInspectionRequired ? '예' : '아니오'],
      ]}
    />
  );
}

function ApprovePanel({
  purchaseRequestId,
  role,
  onDone,
}: {
  purchaseRequestId: number;
  role: string;
  onDone: () => void;
}) {
  const [actionType, setActionType] = useState('');
  const [opinion, setOpinion] = useState('');
  return (
    <Form
      submit="처리"
      onSubmit={async () => {
        if (!actionType) {
          throw new Error('처리 유형을 선택해 주세요.');
        }
        if (actionType === '반려' && opinion.trim() === '') {
          throw new Error('반려할 때는 결재 의견을 입력해 주세요.');
        }
        await call('POST', `/purchase-requests/${purchaseRequestId}/approve`, role, {
          actionType,
          opinion: opinion.trim() === '' ? undefined : opinion.trim(),
        });
        onDone();
      }}
    >
      <Field label="처리 유형" required>
        <Select value={actionType} onChange={setActionType} options={ACTION_OPTIONS} />
      </Field>
      <Field label="결재 의견" wide required={actionType === '반려'}>
        <TextInput value={opinion} onChange={setOpinion} multiline />
      </Field>
    </Form>
  );
}

export default function FnSfr02403Page({ role, notify }: PageProps) {
  const [statusInput, setStatusInput] = useState('');
  const [status, setStatus] = useState('');
  const [page, setPage] = useState(0);
  const [detailId, setDetailId] = useState<number | null>(null);
  const [approveId, setApproveId] = useState<number | null>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/purchase-requests', role, undefined, { approvalStatus: status, page, size: SIZE }),
    [status, page],
  );

  const items = data ? data.items : [];
  const waiting = items.filter((row) => canApprove(row.approvalStatus)).length;

  const columns: Column[] = [
    { key: 'documentNo', label: '문서번호' },
    { key: 'title', label: '품의 제목' },
    { key: 'amount', label: '품의 금액', render: (row) => <Num value={row.amount} /> },
    { key: 'approvalStatus', label: '결재 상태', render: (row) => <Badge value={row.approvalStatus} /> },
    {
      key: 'purchaseRequestId',
      label: '처리',
      render: (row) =>
        canApprove(row.approvalStatus) ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              setApproveId(Number(row.purchaseRequestId));
            }}
          >
            승인 처리
          </button>
        ) : null,
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['이 쪽의 결재 대기', <Num value={waiting} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>구매품의</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setStatus(statusInput);
          }}
          onReset={() => {
            setStatusInput('');
            setStatus('');
            setPage(0);
          }}
        >
          <Field label="결재 상태">
            <Select value={statusInput} onChange={setStatusInput} options={STATUSES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={columns}
          rows={items}
          onRowClick={(row) => setDetailId(Number(row.purchaseRequestId))}
          empty={loading ? '불러오는 중입니다.' : '구매품의가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {detailId !== null ? (
        <Drawer title="구매품의 상세" onClose={() => setDetailId(null)}>
          <DetailPanel purchaseRequestId={detailId} role={role} />
        </Drawer>
      ) : null}
      {approveId !== null ? (
        <Drawer title="구매품의 승인 처리" onClose={() => setApproveId(null)}>
          <ApprovePanel
            purchaseRequestId={approveId}
            role={role}
            onDone={() => {
              notify('처리했습니다.');
              setApproveId(null);
              reload();
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
